<?php
declare(strict_types=1);

function dpa_document_html(array $data): string
{
    $source = __DIR__.'/assets/documents/DISTILLOGIC-DPA-Master-Template-v1.0.txt';
    $text = is_file($source) ? file_get_contents($source) : false;
    if (!is_string($text) || $text === '') throw new RuntimeException('Το master DPA template δεν βρέθηκε.');
    $start = strpos($text, "DISTILLOGIC TECHNOLOGIES\nDATA PROCESSING AGREEMENT");
    if ($start !== false) $text = substr($text, $start);
    $closing = 'Where international transfers, special-category data, large-scale monitoring, healthcare information, financial information or other higher-risk Processing is involved, qualified privacy/legal review is recommended.';
    $end = strpos($text, $closing);
    if ($end !== false) $text = substr($text, 0, $end + strlen($closing));
    $values = [
        '[FULL LEGAL COMPANY NAME]'=>'S. D. MELAS TRADING BUSINESS','[FULL LEGAL NAME]'=>'S. D. MELAS TRADING BUSINESS',
        '[VAT NUMBER]'=>'EL132234268','[GEMI NUMBER]'=>'147185216000','DL-DPA-[NUMBER]'=>(string)($data['dpa_reference']??'DL-DPA-[NUMBER]'),
        '[DATE]'=>(string)($data['effective_date_display']??'[DATE]'),'[CLIENT FULL LEGAL NAME]'=>(string)($data['client_legal_name']??'[CLIENT FULL LEGAL NAME]'),
        '[CLIENT LEGAL NAME]'=>(string)($data['client_legal_name']??'[CLIENT LEGAL NAME]'),'[DESCRIPTION OF SOFTWARE / SERVICE / PROJECT]'=>(string)($data['service_description']??'[DESCRIPTION]'),
        '[DESCRIPTION OF SERVICE / PROJECT]'=>(string)($data['service_description']??'[DESCRIPTION]'),'[PROJECT / CONTRACT DURATION]'=>(string)($data['processing_duration']??'[DURATION]'),
        '[CONTINUOUS / DAILY / PERIODIC / AD HOC]'=>(string)($data['processing_frequency']??'[FREQUENCY]'),'[RETENTION PERIOD / CLIENT INSTRUCTION]'=>(string)($data['retention_period']??'[RETENTION]'),
        '[DESCRIPTION OF SPECIAL CATEGORY DATA]'=>(string)($data['special_categories']??'None expected'),'[EU/EEA COUNTRY]'=>(string)($data['processing_country']??'Greece / European Union'),
        '[CLOUD REGION]'=>(string)($data['cloud_region']??'[CLOUD REGION]'),'[OTHER]'=>(string)($data['other_location']??'N/A'),
        '[10–15]'=>(string)($data['subprocessor_notice_days']??'15'),'[PRIVACY EMAIL]'=>(string)($data['distillogic_privacy_email']??'melas@distillogic.gr'),
    ];
    $text = strtr($text, $values);
    $text = str_replace('having its registered office at [ADDRESS], Patras, Greece', 'having its registered office at Zoodoxou Pigis 11, Patras, Greece', $text);
    $clientName=(string)($data['client_legal_name']??'');
    $text = str_replace($clientName.', having its registered office at [ADDRESS], registration / VAT number [NUMBER],', $clientName.', having its registered office at '.($data['client_address']??'[CLIENT ADDRESS]').', registration / VAT number '.($data['client_registration']??'[NUMBER]').',', $text);
    $text = preg_replace('/E\. Categories of Data Subjects\s+May include:.*?Only applicable categories should remain\./s', "E. Categories of Data Subjects\n".($data['data_subjects']??'[DATA SUBJECTS]'), $text) ?: $text;
    $text = preg_replace('/F\. Categories of Personal Data\s+May include:.*?Only Personal Data actually required by the project should be listed\./s', "F. Categories of Personal Data\n".($data['personal_data_categories']??'[PERSONAL DATA CATEGORIES]'), $text) ?: $text;
    $text = str_replace("Additional Client-specific measures:\n\n[DETAIL]", "Additional Client-specific measures:\n\n".($data['security_measures']??'[DETAIL]'), $text);
    $text = str_replace('Only actual Subprocessors should be listed.', 'Approved subprocessors for this engagement: '.($data['subprocessors']??'[SUBPROCESSORS]')."\n\nOnly actual Subprocessors should be listed.", $text);
    $text = str_replace("Where Personal Data is transferred outside the EEA:\n", "Where Personal Data is transferred outside the EEA:\n\nClient-specific position: ".($data['international_transfers']??'None expected')."\n", $text);
    $text = str_replace("DISTILLOGIC Security Contact\nName / Role: [CONTACT]\nEmail: [EMAIL]\nTelephone: [NUMBER]\n\nClient Security / Privacy Contact\nName / Role: [CONTACT]\nEmail: [EMAIL]\nTelephone: [NUMBER]", "DISTILLOGIC Security Contact\nManaging Director / Privacy Contact\nEmail: melas@distillogic.gr\n\nClient Security / Privacy Contact\n".($data['client_security_contact']??'[CONTACT DETAILS]'), $text);
    $text = str_replace("DISTILLOGIC\nPrivacy Contact: [NAME / ROLE]\nEmail: [PRIVACY EMAIL]\n\nCLIENT\nPrivacy / DPO Contact: [NAME / ROLE]\nEmail: [EMAIL]", "DISTILLOGIC\nPrivacy Contact: Spiros Melas / Managing Director\nEmail: melas@distillogic.gr\n\nCLIENT\nPrivacy / DPO Contact: ".($data['client_privacy_contact']??'[CONTACT DETAILS]'), $text);
    $text = str_replace("DISTILLOGIC\nSecurity Contact: [NAME / ROLE]\nEmail: [EMAIL]\nTelephone: [NUMBER]\n\nPrivacy Contact: [NAME / ROLE]\nEmail: [EMAIL]\n\nCLIENT\nSecurity Contact: [NAME / ROLE]\nEmail: [EMAIL]\n\nPrivacy / DPO Contact: [NAME / ROLE]\nEmail: [EMAIL]", "DISTILLOGIC\nSecurity / Privacy Contact: Spiros Melas, Managing Director\nEmail: melas@distillogic.gr\n\nCLIENT\nSecurity Contact: ".($data['client_security_contact']??'[CONTACT DETAILS]')."\n\nPrivacy / DPO Contact: ".($data['client_privacy_contact']??'[CONTACT DETAILS]'), $text);
    $text = str_replace('[DESCRIPTION]', (string)($data['processing_purpose']??'[DESCRIPTION]'), $text);
    $text = str_replace('[DETAIL]', (string)($data['processing_details']??'[DETAIL]'), $text);
    $text = str_replace('Privacy Contact: [EMAIL]', 'Privacy Contact: '.($data['distillogic_privacy_email']??'melas@distillogic.gr'), $text);
    $text = str_replace('Legal Contact: [EMAIL]', 'Legal Contact: '.($data['distillogic_privacy_email']??'melas@distillogic.gr'), $text);
    $text = str_replace('[ADDRESS]', (string)($data['client_address']??'[CLIENT ADDRESS]'), $text);

    $lines=preg_split('/\R/u',$text)?:[];$content='';$skip=true;$signatures=false;$sectionOpen=false;
    foreach($lines as $line){$line=trim($line);if($skip){if($line==='1. PARTIES')$skip=false;else continue;}if($line==='')continue;
        if($line==='SIGNATURES'){if($sectionOpen){$content.='</section>';$sectionOpen=false;}$signatures=true;$content.='<style>.signatures.bilateral-signatures article{height:160mm;min-height:160mm;display:flex;flex-direction:column}.signature-identity{min-height:64mm}.signature-controls{margin-top:auto}.signature-controls p{margin:0 0 5px}.signature-space{height:68px;border:1px dashed #8aa8ce;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#718399;font-weight:bold}.date-space{height:34px;border-bottom:1px solid #596b80;display:flex;align-items:center;color:#176afc;font-weight:bold}.stamp-space{height:66px;border:1px dashed #8aa8ce;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#718399;font-weight:bold}</style><section class="page-break"><h2>SIGNATURES</h2><div class="signatures bilateral-signatures"><article><h3>FOR DISTILLOGIC</h3><div class="signature-identity"><p><strong>Legal Entity</strong><br>S. D. MELAS TRADING BUSINESS</p><p><strong>Trading Name</strong><br>DISTILLOGIC TECHNOLOGIES</p><p><strong>Name</strong><br>'.e((string)($data['distillogic_signer_name']??'Spiros Melas')).'</p><p><strong>Title</strong><br>'.e((string)($data['distillogic_signer_title']??'Managing Director')).'</p></div><div class="signature-controls"><p><strong>Signature</strong></p><div class="signature-space">AUTHORISED SIGNATURE PLACEHOLDER</div><p><strong>Date</strong></p><div class="date-space"></div><p><strong>Stamp</strong></p><div class="stamp-space">COMPANY STAMP PLACEHOLDER</div></div></article><article><h3>FOR THE CLIENT</h3><div class="signature-identity"><p><strong>Company</strong><br>'.e((string)($data['client_legal_name']??'')).'</p><p><strong>Name</strong><br>'.e((string)($data['client_signer_name']??'')).'</p><p><strong>Title</strong><br>'.e((string)($data['client_signer_title']??'')).'</p><p><strong>Email</strong><br>'.e((string)($data['client_email']??'')).'</p></div><div class="signature-controls"><p><strong>Signature</strong></p><div class="signature-space">AUTHORISED SIGNATURE PLACEHOLDER</div><p><strong>Date</strong></p><div class="date-space"></div><p><strong>Stamp</strong></p><div class="stamp-space">COMPANY STAMP PLACEHOLDER</div></div></article></div></section>';continue;}
        if($signatures){if(strpos($line,'ANNEX 1')===0)$signatures=false;else continue;}
        if(preg_match('/^\d+\.\s+/',$line)){if($sectionOpen)$content.='</section>';$content.='<section class="dpa-section"><h2>'.e($line).'</h2>';$sectionOpen=true;}
        elseif(strpos($line,'ANNEX ')===0||$line==='LEGAL REVIEW NOTICE'){if($sectionOpen)$content.='</section>';$content.='<section class="dpa-section annex"><h2>'.e($line).'</h2>';$sectionOpen=true;}
        elseif(strpos($line,"\t")!==false){$cells=explode("\t",$line);$content.='<div class="table-row">';foreach($cells as $cell)$content.='<span>'.e($cell).'</span>';$content.='</div>';}
        elseif(substr($line,-1)===';'||substr($line,-1)===',')$content.='<div class="bullet">'.e(rtrim($line,';,')).'</div>';else $content.='<p>'.e($line).'</p>';
    }
    if($sectionOpen)$content.='</section>';
    $content='<style>.dpa-section{break-inside:auto!important;page-break-inside:auto!important}.dpa-section h2{break-after:avoid;page-break-after:avoid}.dpa-section p{orphans:3;widows:3}.table-row{grid-template-columns:repeat(5,minmax(0,1fr));break-inside:avoid;page-break-inside:avoid}.table-row span{min-width:0;overflow-wrap:anywhere}.signatures{break-inside:avoid;page-break-inside:avoid}.signatures article{min-height:150mm!important;break-inside:avoid;page-break-inside:avoid}.stamp{margin-top:18px}.footer{margin-top:16px}</style>'.$content;
    $logo=e((string)($data['logo_url']??''));$reference=e((string)($data['dpa_reference']??''));$client=e((string)($data['client_legal_name']??'CLIENT'));
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'.$reference.' - Data Processing Agreement</title><style>@page{size:A4;margin:18mm 17mm 19mm}*{box-sizing:border-box}body{margin:0;color:#142238;background:#fff;font:9.3pt/1.45 Arial,Helvetica,sans-serif}.document{max-width:176mm;margin:auto}.brand{display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #176afc;padding-bottom:12px;margin-bottom:18px}.brand img{width:245px;max-width:57%;height:auto}.meta{text-align:right;color:#5a6b82;font-size:8.5pt}.meta strong{color:#176afc;letter-spacing:.1em}.cover{min-height:255mm;display:flex;flex-direction:column}.cover h1{font-size:31pt;line-height:1.04;margin:37mm 0 8px;color:#071a33}.cover h3{font-size:15pt;color:#176afc;margin:0}.cover-grid{margin-top:23mm;border:1px solid #c1d1e7;border-radius:12px;padding:18px;display:grid;grid-template-columns:1fr 1fr;gap:14px 24px;background:#f5f8fd}.cover-grid strong{display:block;font-size:8pt;text-transform:uppercase;letter-spacing:.07em;color:#607086}.cover-note{margin-top:auto;color:#607086}.dpa-section{margin:0 0 13px}.dpa-section h2{margin:0 0 7px;padding:8px 10px;background:#071a33;color:#fff;font-size:10.8pt}.dpa-section p{margin:0 0 6px;text-align:justify}.bullet{margin:2px 0 2px 16px}.bullet:before{content:"•";color:#176afc;font-weight:bold;margin-left:-12px;margin-right:7px}.annex h2{background:#176afc}.table-row{display:grid;grid-template-columns:repeat(5,1fr);border:1px solid #c5d4e8;border-top:0}.table-row:first-of-type{background:#071a33;color:#fff;font-weight:bold}.table-row span{padding:5px;border-right:1px solid #c5d4e8}.page-break{break-before:page}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:18px}.signatures article{border:1px solid #afbed0;border-radius:10px;padding:16px;min-height:205mm}.signatures h3{background:#071a33;color:#fff;margin:-16px -16px 18px;padding:11px 16px}.signature-line{height:34px;border-bottom:1px solid #596b80}.stamp{height:55px;border:1px dashed #8aa8ce;border-radius:8px;margin-top:20px;display:flex;align-items:center;justify-content:center;color:#176afc;font-weight:bold}.footer{text-align:center;color:#617086;font-size:8pt;margin-top:18px}@media print{.document{max-width:none}.dpa-section h2,.signatures h3{-webkit-print-color-adjust:exact;print-color-adjust:exact}.dpa-section,.signatures article{break-inside:avoid;page-break-inside:avoid}}</style></head><body><main class="document"><section class="cover"><div class="brand"><img src="'.$logo.'" alt="DISTILLOGIC TECHNOLOGIES"><div class="meta"><strong>COMMERCIAL CONFIDENTIAL</strong><br>'.$reference.'<br>Version '.e((string)($data['version']??'1.0')).'</div></div><h1>DATA PROCESSING<br>AGREEMENT</h1><h3>DISTILLOGIC TECHNOLOGIES x '.$client.'</h3><div class="cover-grid"><div><strong>Effective Date</strong>'.e((string)($data['effective_date_display']??'')).'</div><div><strong>Roles</strong>Client: Controller / DISTILLOGIC: Processor</div><div><strong>Service</strong>'.e((string)($data['service_description']??'')).'</div><div><strong>Processing Location</strong>'.e((string)($data['processing_country']??'')).'</div></div><div class="cover-note">S. D. MELAS TRADING BUSINESS<br>trading as DISTILLOGIC TECHNOLOGIES<br>Zoodoxou Pigis 11, Patras, Greece</div></section><div class="page-break"><div class="brand"><img src="'.$logo.'" alt="DISTILLOGIC TECHNOLOGIES"><div class="meta"><strong>COMMERCIAL CONFIDENTIAL</strong><br>'.$reference.'</div></div>'.$content.'<div class="footer">DISTILLOGIC TECHNOLOGIES - Data Processing Agreement - '.$reference.'<br>Legal/privacy review required before execution.</div></div></main></body></html>';
}
